class MinHeap {
  constructor() { this.heap = [null]; }
  get size() { return this.heap.length - 1; }
  peek() { return this.size > 0 ? this.heap[1] : null; }
  _parent(i) { return Math.floor(i/2); }
  _left(i) { return 2*i; }
  _right(i) { return 2*i+1; }
  _swap(i,j) { [this.heap[i],this.heap[j]]=[this.heap[j],this.heap[i]]; }

  insert(val) {
    this.heap.push(val);
    this._siftUp(this.size);
  }
  _siftUp(i) {
    while (i > 1 && this.heap[this._parent(i)] > this.heap[i]) {
      this._swap(i, this._parent(i));
      i = this._parent(i);
    }
  }
  extractMin() {
    if (this.size === 0) return null;
    if (this.size === 1) return this.heap.pop();
    const min = this.heap[1];
    this.heap[1] = this.heap.pop();
    this._siftDown(1);
    return min;
  }
  _siftDown(i) {
    while (true) {
      let s = i; const l = 2*i, r = 2*i+1;
      if (l <= this.size && this.heap[l] < this.heap[s]) s = l;
      if (r <= this.size && this.heap[r] < this.heap[s]) s = r;
      if (s === i) break;
      this._swap(i, s); i = s;
    }
  }
  static fromArray(arr) {
    const h = new MinHeap();
    h.heap = [null, ...arr];
    for (let i = Math.floor(h.size/2); i >= 1; i--) h._siftDown(i);
    return h;
  }
}

function heapSort(arr) {
  const h = MinHeap.fromArray([...arr]);
  const result = [];
  while (h.size > 0) result.push(h.extractMin());
  return result;
}

