function findKthLargestQuickselectImpl(nums, k) {
  const target = nums.length - k;
  function partition(lo, hi) {
    const pivotIdx = lo + Math.floor(Math.random() * (hi - lo + 1));
    [nums[pivotIdx], nums[hi]] = [nums[hi], nums[pivotIdx]];
    const pivot = nums[hi];
    let i = lo - 1;
    for (let j = lo; j < hi; j++) {
      if (nums[j] <= pivot) { i++; [nums[i],nums[j]]=[nums[j],nums[i]]; }
    }
    [nums[i+1],nums[hi]]=[nums[hi],nums[i+1]];
    return i + 1;
  }
  let lo = 0, hi = nums.length - 1;
  while (lo < hi) {
    const p = partition(lo, hi);
    if (p === target) break;
    else if (p < target) lo = p + 1;
    else hi = p - 1;
  }
  return nums[target];
