function topKFrequentBucketImpl(nums, k) {
  const freq = new Map();
  for (const n of nums) freq.set(n, (freq.get(n) || 0) + 1);
  const buckets = new Array(nums.length + 1).fill(null).map(() => []);
  for (const [el, fr] of freq) buckets[fr].push(el);
  const result = [];
  for (let f = buckets.length - 1; f >= 1 && result.length < k; f--) {
    result.push(...buckets[f]);
  }
  return result.slice(0, k);
}

function topKFrequentHeapImpl(nums, k) {
  const freq = new Map();
  for (const n of nums) freq.set(n, (freq.get(n) || 0) + 1);
  const heap = [];
  for (const [el, fr] of freq) heap.push([fr, el]);
  heap.sort((a, b) => b[0] - a[0]);
  return heap.slice(0, k).map(p => p[1]);
}

function sameTopK(nums, k) {
  const a = new Set(topKFrequentBucketImpl(nums, k));
  const b = topKFrequentHeapImpl(nums, k);
  return b.every(x => a.has(x)) && a.size === k;
}

