function kClosestImpl(points, k) {
  const sqDist = ([x,y]) => x*x+y*y;
  const maxHeap = [];
  for (const point of points) {
    const dist = sqDist(point);
    maxHeap.push({dist, point});
    maxHeap.sort((a,b) => b.dist - a.dist);
    if (maxHeap.length > k) maxHeap.shift();
