function mergeKListsImpl(lists) {
  const dummy = new ListNode(0);
  let curr = dummy;
  const heap = [];
  for (let i = 0; i < lists.length; i++) {
    if (lists[i]) heap.push([lists[i].val, i, lists[i]]);
  }
  heap.sort((a,b) => a[0]-b[0]);
  while (heap.length) {
    const [val, idx, node] = heap.shift();
    curr.next = node;
    curr = curr.next;
    if (node.next) {
      const next = node.next;
      const entry = [next.val, idx, next];
      let lo=0, hi=heap.length;
      while (lo<hi){const mid=(lo+hi)>>1;if(heap[mid][0]<entry[0])lo=mid+1;else hi=mid;}
      heap.splice(lo,0,entry);
    }
  }
  return dummy.next;
}

