class Twitter {
  constructor(){
    this.timestamp=0;
    this.tweets=new Map();
    this.following=new Map();
  }
  postTweet(userId,tweetId){
    if(!this.tweets.has(userId))this.tweets.set(userId,[]);
    this.tweets.get(userId).unshift([this.timestamp++,tweetId]);
  }
  getNewsFeed(userId){
    const users=new Set([userId]);
    if(this.following.has(userId))for(const f of this.following.get(userId))users.add(f);
    const heap=[];
    for(const uid of users){
      const ut=this.tweets.get(uid);
      if(ut&&ut.length>0)heap.push([ut[0][0],ut[0][1],uid,0]);
    }
    heap.sort((a,b)=>b[0]-a[0]);
    const feed=[];
    while(feed.length<10&&heap.length){
      const[ts,tweetId,uid,idx]=heap.shift();
      feed.push(tweetId);
      const ut=this.tweets.get(uid);
      if(idx+1<ut.length){
        const next=ut[idx+1];
        heap.push([next[0],next[1],uid,idx+1]);
        heap.sort((a,b)=>b[0]-a[0]);
      }
    }
    return feed;
  }
  follow(fId,eeId){
    if(!this.following.has(fId))this.following.set(fId,new Set());
    this.following.get(fId).add(eeId);
  }
  unfollow(fId,eeId){
    if(this.following.has(fId))this.following.get(fId).delete(eeId);
  }
}

