  const s = new Set(signals);
  if (s.has('k_largest')||s.has('k_smallest')||s.has('k_closest')||s.has('k_frequent')) return 'Top-K';
  if (s.has('merge_k_sorted')||s.has('k_way_merge')||s.has('k_sorted_streams')) return 'K-Way Merge';
  if (s.has('median_from_stream')||s.has('running_percentile')||s.has('sliding_median')) return 'Running Statistics';
  return 'Unknown';
}

function solveTopK(nums, k) {
  const heap = new MinHeap();
  for (const num of nums) { heap.insert(num); if (heap.size > k) heap.extractMin(); }
  return heap.peek();
}

function solveKWayMerge(sortedArrays) {
  // Initialize heap with [value, arrayIndex, elementIndex]
  const heap = [];
  for (let i = 0; i < sortedArrays.length; i++) {
    if (sortedArrays[i].length > 0) heap.push([sortedArrays[i][0], i, 0]);
  }
  heap.sort((a,b) => a[0]-b[0]);
  const result = [];
  while (heap.length) {
    const [val, ai, ei] = heap.shift();
    result.push(val);
    if (ei + 1 < sortedArrays[ai].length) {
      const entry = [sortedArrays[ai][ei+1], ai, ei+1];
      let lo=0,hi=heap.length;
      while(lo<hi){const mid=(lo+hi)>>1;if(heap[mid][0]<entry[0])lo=mid+1;else hi=mid;}
      heap.splice(lo,0,entry);
    }
  }
  return result;
}

function solveRunningMedian(stream) {
  const minHeap = new MinHeap();
  const maxHeap = new MinHeap(); // stores negated values
  const medians = [];
  for (const num of stream) {
    if (maxHeap.size === 0 || num <= -maxHeap.peek()) maxHeap.insert(-num);
    else minHeap.insert(num);
    if (maxHeap.size > minHeap.size + 1) minHeap.insert(-maxHeap.extractMin());
    else if (minHeap.size > maxHeap.size) maxHeap.insert(-minHeap.extractMin());
    if (maxHeap.size > minHeap.size) medians.push(-maxHeap.peek());
    else medians.push((-maxHeap.peek() + minHeap.peek()) / 2);
  }
  return medians;
}

function moduleCapabilitySummary() {
  return {
    topK: solveTopK([3,2,1,5,6,4], 2) === 5,
    kWayMerge: JSON.stringify(solveKWayMerge([[1,4,5],[1,3,4],[2,6]])) === '[1,1,2,3,4,4,5,6]',
    runningMedian: JSON.stringify(solveRunningMedian([1,2,3])) === '[1,1.5,2]'
  };
}
